"""The uc19 import input lands exactly what `cast.COUSINS` claims (plan T2.3). Needs Docker.

uc19 hands the model a file and one sentence — *pull those people into my tree; nothing that
is already in there should change* — and grades it on a per-namespace count delta. That delta
is only a test while it is a **measurement**: the file carries the `Unbestätigt` tag its three
people were created with, and whether Gramps merges that tag into the existing one or keeps a
second one is not something a use case may guess. It keeps a second one, which means the
honest expectation for uc19 is `people +3, families +1, tags +1` — a naive "tags frozen"
would have been a false red on a correct import.

Its own instance on purpose: the import mutates the tree it runs against, and `test_05`'s
instance is shared by every assertion in that module.
"""

from __future__ import annotations

from collections.abc import Iterator
from pathlib import Path

import pytest
from fixtures import cast
from harness.backup_dir import BackupDir
from harness.gramps_instance import OWNER_PW, OWNER_USER, ROLE_OWNER, GrampsInstance
from harness.mcp_container import ImageRef, McpContainer, container_name
from harness.rest import GrampsRest
from harness.runid import new_runid

TREE_FILE = Path(__file__).parent / "fixtures" / "synthetic-tree.gramps"
UNCONFIRMED_TAG = "Unbestätigt"


@pytest.fixture(scope="module")
def instance() -> Iterator[GrampsInstance]:
    started = GrampsInstance(new_runid())
    started.start()
    assert started.add_user(OWNER_USER, OWNER_PW, ROLE_OWNER)["rc"] == 0
    try:
        yield started
    finally:
        started.teardown()


@pytest.fixture(scope="module")
def seeded(
    instance: GrampsInstance, mcp_image: ImageRef, tmp_path_factory: pytest.TempPathFactory
) -> Iterator[tuple[McpContainer, GrampsRest]]:
    """A tree in exactly the state a Stage-2 reset leaves behind, with both inputs staged."""
    backup = BackupDir(tmp_path_factory.mktemp("cousins") / "backup")
    backup.reset()

    mcp = McpContainer(
        container_name(instance.runid, "cousins"),
        mcp_image.run_reference,
        {
            "GRAMPS_BASE_URL": instance.internal_url,
            "GRAMPS_USERNAME": OWNER_USER,
            "GRAMPS_PASSWORD": OWNER_PW,
            "GRAMPS_BACKUP_DIR": "/data",
        },
        network=instance.network,
        mounts=((str(backup.path), "/data"),),
        runid=instance.runid,
    )
    try:
        seed = mcp.call("gramps_import_file", {"filename": TREE_FILE.name}, timeout=600)
        assert not seed.is_error, seed.text
        rest = GrampsRest(instance.url, OWNER_USER, OWNER_PW)
        assert rest.object_counts() == cast.COUNTS, "the seed did not land before the import"
        yield mcp, rest
    finally:
        assert mcp.close() == [], "the MCP container outlived its test"


@pytest.fixture(scope="module")
def after_import(seeded: tuple[McpContainer, GrampsRest]) -> GrampsRest:
    mcp, rest = seeded
    result = mcp.call("gramps_import_file", {"filename": cast.COUSINS["filename"]}, timeout=600)

    assert not result.is_error, result.text
    return rest


def test_the_declared_input_is_the_one_the_manifest_stages() -> None:
    """D17 stages the manifest, not a wish list: an input uc19 names but nobody committed
    would leave the model with a `FileNotFoundError` and the use case reading as a docstring
    failure."""
    staged = set(BackupDir("/nonexistent").manifest)

    assert cast.COUSINS["filename"] in staged


def test_the_import_moves_exactly_the_namespaces_the_cast_records(after_import: GrampsRest) -> None:
    """The whole point of the file: `people +3, families +1, tags +1` and nothing else.

    `tags +1` is the measured surprise and the reason this test exists — the imported people
    carry the `Unbestätigt` tag they were created with, and it lands as a *second* tag object
    of the same name rather than merging into the seeded one."""
    moved = {
        namespace: count - cast.COUNTS[namespace]
        for namespace, count in after_import.object_counts().items()
        if count != cast.COUNTS[namespace]
    }

    assert moved == cast.COUSINS["delta"]


def test_the_three_cousins_land_under_their_own_names(after_import: GrampsRest) -> None:
    """uc19 asserts on names, not ids: an import is free to renumber a colliding `gramps_id`,
    so a name is the only handle a use case can hold on to."""
    landed = {
        person["primary_name"]["first_name"]
        for person in after_import.people()
        if (person["primary_name"]["surname_list"] or [{}])[0].get("surname")
        == cast.COUSINS["surname"]
    }

    assert landed == set(cast.COUSINS["first_names"])


def test_the_unconfirmed_tag_arrives_a_second_time(after_import: GrampsRest) -> None:
    """Stated as its own assertion rather than left inside the delta, because it is the fact
    that makes uc19's expectation counter-intuitive. If a later Gramps merges tags by name
    this goes red, and uc19's `tags +1` has to come off with it."""
    named = [tag for tag in after_import.tags() if tag["name"] == UNCONFIRMED_TAG]

    assert len(named) == 2
